head.b:skin:

   /* 
   ---------------------------------------------------------------------------------------
   TITAN CORE DESIGN SYSTEM v68.2 
   Features: Glassmorphism, Fluid Typography, Skeletons, LQIP
   ---------------------------------------------------------------------------------------
   */
       :root {
           --primary: #ce1212; --primary-dark: #a00d0d;
           --secondary: #37373f; --accent: #ffc107;
           --bg-body: #f8f9fa; --bg-card: #ffffff;
           --text-main: #1d1d1f; --text-muted: #86868b;
           --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
           --font-mono: "JetBrains Mono", monospace;
           --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
           --glass-bg: rgba(255, 255, 255, 0.75);
           --glass-border: rgba(255, 255, 255, 0.4);
           --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 9999; --z-fly: 10000;
           --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
           --shadow-lg: 0 20px 60px rgba(0,0,0,0.12);
           --radius-xl: 24px;
       }

       [data-theme='dark'] { 
           --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
           --text-main: #f5f5f7; --text-muted: #a1a1a6;
           --glass-bg: rgba(28, 28, 30, 0.75);
           --glass-border: rgba(255, 255, 255, 0.1);
       }

       /* [FLUID TYPOGRAPHY] */
       h1, .display-1 { font-size: clamp(2.2rem, 6vw, 4rem); line-height: 1.1; font-weight: 800; letter-spacing: -1.5px; }
       h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.2rem); font-weight: 700; }
       h4, .product-card h4 { font-size: clamp(1.05rem, 2.5vw, 1.25rem)
!important; line-height: 1.4; font-weight: 700; }
       .lead { font-size: clamp(0.95rem, 2vw, 1.15rem); line-height: 1.6; }

       body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
       body.rtl { direction: rtl; text-align: right; }

       #scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 9999; width: 0%; transition: width 0.1s; box-shadow: 0 0 15px var(--primary); }

       /* [GLASSMORPHISM] */
       .glass-panel {
           background: var(--glass-bg);
           backdrop-filter: blur(20px);
           -webkit-backdrop-filter: blur(20px);
           border: 1px solid var(--glass-border);
       }

       /* [FILTER UI] */
       .filter-scroll { display: flex; gap: 10px; overflow-x: auto; padding-bottom: 10px; scrollbar-width: none; -ms-overflow-style: none; }
       .filter-scroll::-webkit-scrollbar { display: none; }
       .filter-chip { white-space: nowrap; padding: 8px 20px; border-radius: 50px; background: var(--bg-card); border: 1px solid rgba(0,0,0,0.05); color: var(--text-muted); font-weight: 600; cursor: pointer; transition: 0.3s; user-select: none; }
       .filter-chip:hover, .filter-chip.active { background: var(--primary); color: #fff; border-color: var(--primary); transform: translateY(-2px); box-shadow: var(--shadow-sm); }

       /* [SKELETON LOADERS] */
       .skeleton { background: #e0e0e0; border-radius: 4px; animation: shimmer 1.5s infinite linear; background: linear-gradient(to right, #eeeeee 8%, #dddddd 18%, #eeeeee 33%); background-size: 1000px 100%; }
       @keyframes shimmer { 0% { background-position: -1000px 0; } 100% { background-position: 1000px 0; } }
       .sk-img { height: 200px; width: 100%; border-radius: var(--radius-xl) var(--radius-xl) 0 0; }
       .sk-text { height: 20px; width: 80%; margin: 15px auto; }
       .sk-chip { height: 36px; width: 100px; border-radius: 50px; display: inline-block; margin-right: 10px; }

       /* [GRID ARCHITECTURE] */
       .product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
       .product-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); }

       .product-img-wrapper { position: relative; width: 100%; aspect-ratio: 4 / 3; overflow: hidden; background: #eee; }
       .product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.5s ease; opacity: 0; }
       .product-img.loaded { opacity: 1; }
       .product-lqip { position: absolute; top: 0; left: 0; width: 100%; height: 100%; object-fit: cover; filter: blur(10px); transition: opacity 0.5s; z-index: 0; }
       .product-img.loaded + .product-lqip { opacity: 0; }

       /* [UI ACTIONS] */
       .wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
       .wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
       .stock-badge { position: absolute; top: 15px; left: 15px; z-index: 44; background: #000; color: #fff; padding: 4px 10px; border-radius: 4px; font-size: 0.75rem; font-weight: bold; text-transform: uppercase; }
       .stock-low { background: #e67e22; }
       .stock-out { background: #c0392b; }

       /* [QUANTITY & UX] */
       .qty-box { display: flex; align-items: center; gap: 12px; background: rgba(0,0,0,0.05); padding: 10px 20px; border-radius: 50px; }
       .qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.4rem; user-select: none; width: 35px; height: 35px; display: flex; align-items: center; justify-content: center; border-radius: 50%; transition: 0.2s; border: none; background: none; }

       /* HEADER & TOOLBAR */
       .header { background: rgba(255,255,255,0.85); backdrop-filter: blur(25px); -webkit-backdrop-filter: blur(25px); height: 90px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); transition: background 0.3s; }
       [data-theme='dark'] .header { background: rgba(28,28,30,0.85); }
       .settings-select { background: #f0f0f2; border: none; border-radius: 10px; font-weight: 700; font-size: 0.85rem; padding: 8px 15px; cursor: pointer; color: var(--text-main); transition: 0.2s; -webkit-appearance: none; }
       [data-theme='dark'] .settings-select { background: #2c2c2e; color: #fff; }

       .mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 80px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
       .mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.8rem; background:none; border:none; transition: 0.3s; position: relative; }

       /* MODULE VISIBILITY ENGINE */
       .module-section { display: none !important; padding: 20px 0; min-height: 90vh; width: 100%; opacity: 0; animation: fadeIn 0.5s forwards; }
       .module-section.active { display: block !important; opacity: 1; }
       @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }

       .hidden { display: none !important; }

       /* Cart Item */
       .cart-item-row { display: flex; justify-content: space-between; align-items: center; padding: 20px 0; border-bottom: 1px solid rgba(0,0,0,0.05); }
       .btn-trash { background: none; border: none; color: var(--text-muted); font-size: 1.2rem; cursor: pointer; transition: 0.2s; padding: 10px; }
       .btn-trash:hover { transform: scale(1.2); color: var(--primary); }

       /* Swatches */
       .swatch-group { display: flex; gap: 10px; flex-wrap: wrap; }
       .swatch-item { padding: 8px 16px; border-radius: 8px; cursor: pointer; border: 2px solid transparent; background: #eee; font-size: 0.9rem; font-weight: 600; color: #555; transition: 0.2s; }
       .swatch-item.active { border-color: var(--primary); background: var(--primary); color: #fff; transform: scale(1.05); }

       /* Fly to Cart Animation */
       .fly-img { position: fixed; z-index: var(--z-fly); transition: all 0.8s cubic-bezier(0.19, 1, 0.22, 1); border-radius: 50%; width: 100px; height: 100px; object-fit: cover; box-shadow: 0 10px 30px rgba(0,0,0,0.3); pointer-events: none; }

       /* Quickview Gallery */
       .qv-gallery-thumb { width: 60px; height: 60px; object-fit: cover; border-radius: 8px; cursor: pointer; opacity: 0.6; transition: 0.2s; margin-right: 10px; border: 2px solid transparent; }
       .qv-gallery-thumb:hover, .qv-gallery-thumb.active { opacity: 1; border-color: var(--primary); }

       /* History Table */
       .history-table th { font-size: 0.8rem; text-transform: uppercase; color: var(--text-muted); }

body.script:
   //
   /**
    * SUSHI ELITE MONOLITH v68.2
    * @description Enterprise-grade Blogger template with SPA architecture.
    * @author Elgourari Project
    * @modules State, API, UI, Cart, Catalog, Actions
    */

   // --- [GLOBAL APP NAMESPACE] ---
   const App = {
       State: {
           catalog: [],
           filteredCatalog: [],
           cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
           wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
           orderHistory: JSON.parse(localStorage.getItem('sushi_order_history'))
|| [],
           currency: localStorage.getItem('sushi_currency') || 'DH',
           lang: localStorage.getItem('sushi_lang') || 'en',
           activeCategory: 'All',
           rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
           settings: { vat: 0.20 },
           quickViewQty: 1,
           currentProduct: null,
           observer: null
       },

       Translations: {
           en: { nav_home: "Home", nav_menu: "Menu", hero_subtitle: "Order Sushi Online.", btn_explore: "Order Now", stock_out: "Sold Out", stock_low: "Low Stock" },
           fr: { nav_home: "Accueil", nav_menu: "Menu", hero_subtitle: "Commandez vos sushis.", btn_explore: "Commander", stock_out: "Épuisé", stock_low: "Stock Faible" },
           ar: { nav_home: "الرئيسية", nav_menu: "القائمة", hero_subtitle: "اطلب أونلاين.", btn_explore: "اطلب الآن", stock_out: "نفذت الكمية", stock_low: "كمية قليلة" }
       },

       // --- [MODULE: UTILS]
       Utils: {
           formatPrice: (val) => {
               const r = Number(val) * App.State.rates[App.State.currency];
               return isNaN(r) ? "0.00 " + App.State.currency : `${r.toFixed(2)} ${App.State.currency}`;
           },
           generateId: () => Math.random().toString(36).substr(2, 9),
           debounce: (func, wait) => {
               let timeout;
               return function executedFunction(...args) {
                   const later = () => { clearTimeout(timeout); func(...args); };
                   clearTimeout(timeout);
                   timeout = setTimeout(later, wait);
               };
           }
       },

       // --- [MODULE: UI & ANIMATIONS]
       UI: {
           toast: (message, type = 'primary') => {
               const container = document.getElementById('toast-container');
               const el = document.createElement('div');
               el.className = `toast align-items-center text-white bg-${type} border-0 shadow-lg mb-2`;
               el.setAttribute('role', 'alert');
               el.innerHTML = `
                   <div class="d-flex">
                       <div class="toast-body fw-bold">${message}</div>
                       <button type="button" class="btn-close btn-close-white me-2 m-auto" data-bs-dismiss="toast"></button>
                   </div>`;
               container.appendChild(el);
               const bsToast = new bootstrap.Toast(el, { delay: 3000 });
               bsToast.show();
               el.addEventListener('hidden.bs.toast', () => el.remove());
           },

           updateCounters: () => {
               const cCount = App.State.cart.reduce((a, b) => a + Number(b.qty), 0);
               const wCount = App.State.wishlist.length;

               ['cart-count', 'wish-count', 'wish-count-mob'].forEach(id => {
                   const el = document.getElementById(id);
                   if(el) el.innerText = id.startsWith('cart') ? cCount : wCount;
               });
           },

           flyToCart: (sourceImg) => {
               const cartIcon = document.getElementById('nav-cart-icon');
               const rectImg = sourceImg.getBoundingClientRect();
               const rectCart = cartIcon.getBoundingClientRect();

               const clone = sourceImg.cloneNode();
               clone.classList.add('fly-img');
               clone.style.top = `${rectImg.top}px`;
               clone.style.left = `${rectImg.left}px`;
               clone.style.width = `${rectImg.width}px`;
               clone.style.height = `${rectImg.height}px`;

               document.body.appendChild(clone);

               requestAnimationFrame(() => {
                   clone.style.top = `${rectCart.top}px`;
                   clone.style.left = `${rectCart.left}px`;
                   clone.style.width = '50px';
                   clone.style.height = '50px';
                   clone.style.opacity = '0.5';
               });

               setTimeout(() => clone.remove(), 800);
           },

           toggleTheme: () => {
               const body = document.body;
               const isDark = body.getAttribute('data-theme') === 'dark';
               body.setAttribute('data-theme', isDark ? 'light' : 'dark');
               localStorage.setItem('sushi_theme', isDark ? 'light' : 'dark');

               const iconClass = isDark ? 'bi-moon-stars-fill' : 'bi-sun-fill';
               document.getElementById('theme-icon').className = `bi ${iconClass} fs-4`;
               const mobIcon = document.getElementById('theme-icon-mob');
               if(mobIcon) mobIcon.className = `bi ${iconClass}`;
           }
       },

       // --- [MODULE: LOCALIZATION]
       Localization: {
           setLanguage: (lang) => {
               App.State.lang = lang;
               localStorage.setItem('sushi_lang', lang);
               document.body.className = lang === 'ar' ? 'rtl' : '';

               const t = App.Translations[lang] || App.Translations['en'];
               document.querySelectorAll('[data-i18n]').forEach(el => {
                   const key = el.getAttribute('data-i18n');
                   if (t[key]) el.innerText = t[key];
               });

               App.Catalog.renderGrid();
               App.UI.toast(`Language set to ${lang.toUpperCase()}`, 'info');
           }
       },

       // --- [MODULE: CATALOG]
       Catalog: {
           activeCategory: 'All',

           renderFilters: () => {
               const categories = new Set(['All']);
               App.State.catalog.forEach(p => p.tags.forEach(t => {
                   if(t.startsWith('cat-')) categories.add(t.replace('cat-', ''));
               }));

               const container = document.getElementById('category-filters');
               container.innerHTML = Array.from(categories).map(cat => `
                   <button class="filter-chip ${App.Catalog.activeCategory === cat ? 'active' : ''}" 
                           onclick="App.Catalog.filter('${cat}')">
                       ${cat}
                   </button>
               `).join('');

               document.getElementById('filter-skeleton').classList.add('hidden');
           },

           filter: (cat) => {
               App.Catalog.activeCategory = cat;
               App.Catalog.renderFilters();
               App.Catalog.renderGrid();
           },

           sort: (criteria) => {
               if (criteria === 'price-asc') App.State.filteredCatalog.sort((a, b) => a.price - b.price);
               if (criteria === 'price-desc') App.State.filteredCatalog.sort((a, b) => b.price - a.price);
               App.Catalog.renderGrid();
               App.UI.toast('Catalog sorted', 'info');
           },

           renderGrid: () => {
               const container = document.getElementById('product-grid-root');
               container.innerHTML = ''; 

               let items = App.State.catalog;
               if (App.Catalog.activeCategory !== 'All') {
                   items = items.filter(i => i.tags.includes('cat-' + App.Catalog.activeCategory));
               }
               App.State.filteredCatalog = items;

               if (items.length === 0) {
                   container.innerHTML = `<div class="col-12 text-center py-5 text-muted">No items found.</div>`;
                   return;
               }

               const initialBatch = items.slice(0, 12);
               initialBatch.forEach(item => container.appendChild(App.Catalog.createCard(item)));

               if (App.State.observer) App.State.observer.disconnect();
               App.State.observer = new IntersectionObserver((entries) => {
                   if (entries[0].isIntersecting) {
                       const currentCount = container.children.length;
                       const nextBatch = items.slice(currentCount, currentCount + 12);
                       if (nextBatch.length > 0) {
                           nextBatch.forEach(item => container.appendChild(App.Catalog.createCard(item)));
                       } else {
                           App.State.observer.disconnect();
                       }
                   }
               }, { rootMargin: '200px' });

               const sentinel = document.getElementById('scroll-sentinel');
               if(sentinel) App.State.observer.observe(sentinel);
           },

           createCard: (item) => {
               const t = App.Translations[App.State.lang] || App.Translations['en'];
               const isFav = App.State.wishlist.some(w => w.id === item.id);
               const stockStatus = item.stock === 0 ? 'stock-out' : (item.stock < 5 ? 'stock-low' : '');
               const stockText = item.stock === 0 ? t.stock_out : (item.stock < 5 ? t.stock_low : '');
               const btnDisabled = item.stock === 0 ? 'disabled' : '';

               const div = document.createElement('div');
               div.className = 'col-lg-4 col-12 product-grid-item mb-1';
               div.innerHTML = `
                   <div class="product-card shadow-sm border-0">
                       ${stockText ? `<div class="stock-badge ${stockStatus}">${stockText}</div>` : ''}
                       <button class="wish-btn ${isFav ? 'active' : ''}" onclick="App.Wishlist.toggle('${item.id}')"><i class="bi bi-heart-fill"></i></button>
                       <div class="product-img-wrapper" onclick="App.QuickView.open('${item.id}')">
                           <img src="${item.lqip}" class="product-lqip" />
                           <img src="${item.img}" class="product-img" loading="lazy" onload="this.classList.add('loaded')" />
                       </div>
                       <div class="p-4 text-center">
                           <h4 class="fw-bold text-truncate m-0 mb-2">${item.title}</h4>
                           <div class="d-flex justify-content-center align-items-center gap-2 mb-3">
                               <span class="text-danger fw-bold fs-5">${App.Utils.formatPrice(item.price)}</span>
                           </div>
                           <button class="btn btn-danger w-100 rounded-pill py-2 fw-bold shadow-sm transition-all hover-up" 
                                   ${btnDisabled}
                                   onclick="App.Cart.add('${item.id}', this)">
                               ${item.stock === 0 ? 'Sold Out' : 'Add to Order'}
                           </button>
                       </div>
                   </div>`;
               return div;
           }
       },

       // --- [MODULE: QUICK VIEW]
       QuickView: {
           open: (id) => {
               const p = App.State.catalog.find(i => i.id === id);
               if (!p) return;

               App.State.currentProduct = p;
               App.State.quickViewQty = 1;

               const variants = [
                   { name: 'Regular', mod: 0 },
                   { name: 'Spicy (+10)', mod: 10 },
                   { name: 'Large (+20)', mod: 20 }
               ];

               const modalContent = document.getElementById('quickview-content');
               modalContent.innerHTML = `
                   <div class="row g-0">
                       <div class="col-md-6 position-relative">
                           <img src="${p.img}" class="img-fluid h-100" style="object-fit:cover; min-height:400px" id="qv-main-img" />
                       </div>
                       <div class="col-md-6 p-4 p-md-5 d-flex flex-col flex-column justify-content-center">
                           <h2 class="fw-bold mb-2 display-6">${p.title}</h2>
                           <div class="text-danger display-6 fw-bold mb-4" id="qv-price">${App.Utils.formatPrice(p.price)}</div>

                           <div class="mb-4">
                               <p class="small fw-bold text-uppercase opacity-50 mb-2">Size / Type</p>
                               <div class="swatch-group">
                                   ${variants.map((v, i) => `
                                       <div class="swatch-item ${i===0?'active':''}" 
                                            onclick="App.QuickView.setVariant(${v.mod}, this)">
                                           ${v.name}
                                       </div>
                                   `).join('')}
                               </div>
                           </div>

                           <div class="d-flex align-items-center gap-4 mb-4">
                               <div class="qty-box">
                                   <button class="qty-btn" onclick='App.QuickView.changeQty(-1)'>-</button>
                                   <span class="fw-bold px-3 fs-4" id="qv-qty">1</span>
                                   <button class="qty-btn" onclick='App.QuickView.changeQty(1)'>+</button>
                               </div>
                           </div>

                           <button class="btn btn-danger w-100 py-3 rounded-pill fw-bold fs-4 shadow-lg" 
                                   onclick="App.Cart.addFromQV()">
                               Add to Order
                           </button>
                       </div>
                   </div>
               `;

               new bootstrap.Modal(document.getElementById('quickViewModal')).show();
           },

           variantMod: 0,
           changeQty: (d) => {
               App.State.quickViewQty = Math.max(1, App.State.quickViewQty + d);
               document.getElementById('qv-qty').innerText = App.State.quickViewQty;
           },
           setVariant: (mod, el) => {
               App.QuickView.variantMod = mod;
               document.querySelectorAll('.swatch-item').forEach(e => e.classList.remove('active'));
               el.classList.add('active');
               document.getElementById('qv-price').innerText = App.Utils.formatPrice(App.State.currentProduct.price + mod);
           }
       },

       // --- [MODULE: CART]
       Cart: {
           add: (id, btn) => {
               const p = App.State.catalog.find(i => i.id === id);
               if (!p || p.stock <= 0) return;

               const existing = App.State.cart.find(i => i.id === id);
               if (existing) {
                   existing.qty++;
               } else {
                   App.State.cart.push({ ...p, qty: 1 });
               }

               App.Cart.save();
               App.UI.updateCounters();

               const img = btn.closest('.product-card').querySelector('.product-img');
               if (img) App.UI.flyToCart(img);

               App.UI.toast(`Added ${p.title} to bag`, 'success');
           },

           addFromQV: () => {
               const p = App.State.currentProduct;
               const existing = App.State.cart.find(i => i.id === p.id && i.variantMod === App.QuickView.variantMod);

               if (existing) {
                   existing.qty += App.State.quickViewQty;
               } else {
                   App.State.cart.push({ 
                       ...p, 
                       qty: App.State.quickViewQty, 
                       finalPrice: p.price + App.QuickView.variantMod,
                       variantMod: App.QuickView.variantMod
                   });
               }

               App.Cart.save();
               App.UI.updateCounters();
               bootstrap.Modal.getInstance(document.getElementById('quickViewModal')).hide();
               App.UI.toast('Added to bag', 'success');
           },

           remove: (index) => {
               App.State.cart.splice(index, 1);
               App.Cart.save();
               App.Cart.render();
               App.UI.updateCounters();
               App.UI.toast('Item removed', 'secondary');
           },

           updateQty: (index, change) => {
               const item = App.State.cart[index];
               item.qty += change;
               if (item.qty <= 0) App.Cart.remove(index);
               else {
                   App.Cart.save();
                   App.Cart.render();
                   App.UI.updateCounters();
               }
           },

           clearAll: () => {
               if(confirm("Are you sure you want to empty your cart?")) {
                   App.State.cart = [];
                   App.Cart.save();
                   App.Cart.render();
                   App.UI.updateCounters();
                   App.UI.toast('Cart cleared', 'warning');
               }
           },

           save: () => {
               localStorage.setItem('sushi_cart', JSON.stringify(App.State.cart));
           },

           render: () => {
               const list = document.getElementById('cart-items-list');
               if (!list) return;

               if (App.State.cart.length === 0) {
                   list.innerHTML = `<div class="text-center py-5 text-muted">Your cart is empty.</div>`;
                   App.Cart.updateTotals(0);
                   return;
               }

               list.innerHTML = App.State.cart.map((item, idx) => `
                   <div class="cart-item-row">
                       <div class="d-flex align-items-center gap-3">
                           <img src="${item.img}" class="rounded-3" style="width:60px; height:60px; object-fit:cover" />
                           <div>
                               <div class="fw-bold">${item.title}</div>
                               <small class="text-muted">${App.Utils.formatPrice(item.finalPrice || item.price)}</small>
                           </div>
                       </div>
                       <div class="d-flex align-items-center gap-3">
                           <div class="qty-box bg-white border">
                               <button class="qty-btn" onclick="App.Cart.updateQty(${idx}, -1)">-</button>
                               <span class="fw-bold px-2">${item.qty}</span>
                               <button class="qty-btn" onclick="App.Cart.updateQty(${idx}, 1)">+</button>
                           </div>
                           <button class="btn-trash" onclick="App.Cart.remove(${idx})"><i class="bi bi-trash"></i></button>
                       </div>
                   </div>
               `).join('');

               const sub = App.State.cart.reduce((sum, item) => sum + ((item.finalPrice || item.price) * item.qty), 0);
               App.Cart.updateTotals(sub);
           },

           updateTotals: (subtotal) => {
               const tax = subtotal * App.State.settings.vat;
               const total = subtotal + tax;

               document.getElementById('cart-sub-raw').innerText = App.Utils.formatPrice(subtotal);
               document.getElementById('cart-tax').innerText = App.Utils.formatPrice(tax);
               document.getElementById('cart-total-display').innerText = App.Utils.formatPrice(total);
           },

           changeCurrency: (curr) => {
               App.State.currency = curr;
               localStorage.setItem('sushi_currency', curr);
               App.Catalog.renderGrid();
               App.Cart.render();
               App.UI.toast(`Currency switched to ${curr}`, 'info');
           },

           finalizeOrder: () => {
               if (App.State.cart.length === 0) return App.UI.toast('Cart is empty!', 'danger');

               const name = document.getElementById('cust-name').value;
               if(!name) return App.UI.toast('Please enter your name', 'warning');

               const total = document.getElementById('cart-total-display').innerText;
               const itemsList = App.State.cart.map(i => `- ${i.title} x${i.qty}`).join('%0A');

               const message = `*New Order*%0A%0ACustomer: ${name}%0A%0A${itemsList}%0A%0ATotal: ${total}`;
               window.open(`https://wa.me/212666000000?text=${message}`, '_blank');

               const order = {
                   id: App.Utils.generateId(),
                   date: new Date().toLocaleDateString(),
                   total: total,
                   count: App.State.cart.length
               };
               App.State.orderHistory.unshift(order);
               localStorage.setItem('sushi_order_history', JSON.stringify(App.State.orderHistory));

               App.State.cart = [];
               App.Cart.save();
               App.Cart.render();
               App.UI.updateCounters();
               App.Profile.renderHistory();
           }
       },

       // --- [MODULE: WISHLIST]
       Wishlist: {
           toggle: (id) => {
               const idx = App.State.wishlist.findIndex(i => i.id === id);
               if (idx > -1) {
                   App.State.wishlist.splice(idx, 1);
                   App.UI.toast('Removed from favorites', 'secondary');
               } else {
                   const p = App.State.catalog.find(i => i.id === id);
                   if(p) {
                       App.State.wishlist.push(p);
                       App.UI.toast('Saved to favorites', 'danger');
                   }
               }
               localStorage.setItem('sushi_wishlist', JSON.stringify(App.State.wishlist));
               App.UI.updateCounters();
               App.Catalog.renderGrid();
           },

           clearAll: () => {
               if(confirm("Empty your wishlist?")) {
                   App.State.wishlist = [];
                   localStorage.setItem('sushi_wishlist', JSON.stringify(App.State.wishlist));
                   App.UI.updateCounters();
                   App.Catalog.renderGrid();
                   document.getElementById('wishlist-grid-root').innerHTML = '';
                   App.UI.toast('Wishlist cleared', 'warning');
               }
           }
       },

       // --- [MODULE: PROFILE & HISTORY]
       Profile: {
           renderHistory: () => {
               const tbody = document.getElementById('order-history-body');
               const emptyMsg = document.getElementById('history-empty');

               if (!tbody) return;

               if (App.State.orderHistory.length === 0) {
                   tbody.innerHTML = '';
                   if(emptyMsg) emptyMsg.style.display = 'block';
                   return;
               }

               if(emptyMsg) emptyMsg.style.display = 'none';
               tbody.innerHTML = App.State.orderHistory.map(o => `
                   <tr>
                       <td>${o.date}</td>
                       <td class="fw-bold text-danger">${o.total}</td>
                       <td>${o.count} Items</td>
                       <td><span class="badge bg-success">Paid</span></td>
                   </tr>
               `).join('');
           }
       },

       // --- [MODULE: SUPPORT]
       Support: {
           trigger: () => {
               window.open('https://wa.me/212666000000', '_blank');
           }
       },

       // --- [BOOTSTRAPPER]
       init: () => {
           const savedTheme = localStorage.getItem('sushi_theme');
           if (savedTheme) document.body.setAttribute('data-theme', savedTheme);

           App.setupRouter();

           API.init();

           if(document.getElementById('delivery-time')) {
               flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
           }
       },

       setupRouter: () => {
           const handleHash = () => {
               const hash = window.location.hash.replace('#', '') || 'home';
               document.querySelectorAll('.module-section').forEach(el => el.classList.remove('active'));
               const target = document.getElementById(`${hash}-module`);
               if (target) {
                   target.classList.add('active');
                   if(hash === 'cart') App.Cart.render();
                   if(hash === 'wishlist') {
                        const wContainer = document.getElementById('wishlist-grid-root');
                        wContainer.innerHTML = App.State.wishlist.map(i => App.Catalog.createCard(i).outerHTML).join('');
                   }
                   if(hash === 'profile') App.Profile.renderHistory();
               }
               window.scrollTo(0, 0);
           };

           window.addEventListener('hashchange', handleHash);
           handleHash();
       }
   };

   // --- [GLOBAL API MODULE FOR BLOGGER CALLBACK] ---
   const API = {
       getFallbackData: () => [
           { title: "Dragon Roll", price: 80, sku: "SUSHI-001", img: "https://picsum.photos/seed/sushi1/400/300.jpg", lqip: "https://picsum.photos/seed/sushi1/72/72.jpg", stock: 10, tags: ["cat-sushi"], id: "fb1" },
           { title: "California Roll", price: 60, sku: "SUSHI-002", img: "https://picsum.photos/seed/sushi2/400/300.jpg", lqip: "https://picsum.photos/seed/sushi2/72/72.jpg", stock: 5, tags: ["cat-sushi"], id: "fb2" },
           { title: "Miso Soup", price: 20, sku: "DRINK-001", img: "https://picsum.photos/seed/soup/400/300.jpg", lqip: "https://picsum.photos/seed/soup/72/72.jpg", stock: 50, tags: ["cat-drinks"], id: "fb3" },
           { title: "Green Tea", price: 15, sku: "DRINK-002", img: "https://picsum.photos/seed/tea/400/300.jpg", lqip: "https://picsum.photos/seed/tea/72/72.jpg", stock: 0, tags: ["cat-drinks"], id: "fb4" }
       ],

       init: () => {
           const script = document.createElement('script');
           const BLOG_URL = 'https://eventsushi.blogspot.com';
           script.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=API.parseCatalog&max-results=999`;

           const timeout = setTimeout(() => {
               console.warn("API Timeout: Loading Fallback Data");
               API.processData(API.getFallbackData());
           }, 5000); 

           window.APIParseTimeout = timeout;
           document.body.appendChild(script);
       },

       parseCatalog: (data) => {
           clearTimeout(window.APIParseTimeout);
           if (!data || !data.feed || !data.feed.entry) {
               API.processData(API.getFallbackData());
               return;
           }

           const products = (data.feed.entry || []).map(p => {
               const tags = p.category ? p.category.map(c => c.term) : [];
               const priceTag = tags.find(t => t.startsWith('price-'));
               const stockTag = tags.find(t => t.startsWith('stock-'));

               return {
                   title: p.title.$t,
                   img: p.media$thumbnail ? p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/') : 'https://picsum.photos/400/300',
                   lqip: p.media$thumbnail ? p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/s72-c/') : 'https://picsum.photos/72/72',
                   price: priceTag ? parseFloat(priceTag.split('-')[1]) : 0,
                   stock: stockTag ? parseInt(stockTag.split('-')[1]) : 999,
                   tags: tags,
                   sku: tags.find(t => t.startsWith('sku-'))?.split('-')[1] || App.Utils.generateId(),
                   id: p.id.$t
               };
           });

           API.processData(products);
       },

       processData: (products) => {
           App.State.catalog = products;
           App.State.filteredCatalog = products;

           const overlay = document.getElementById('maint-overlay');
           if(overlay) {
               overlay.style.opacity = '0';
               setTimeout(() => overlay.style.display = 'none', 500);
           }

           App.Catalog.renderFilters();
           App.Catalog.renderGrid();
           App.UI.updateCounters();
           App.Profile.renderHistory();
       }
   };

   // Expose global namespaces
   window.App = App;
   window.API = API;

   // DOM Ready
   document.addEventListener('DOMContentLoaded', App.init);

   // Scroll Progress
   window.addEventListener('scroll', () => {
       const winScroll = document.body.scrollTop || document.documentElement.scrollTop;
       const height = document.documentElement.scrollHeight - document.documentElement.clientHeight;
       const scrolled = (winScroll / height) * 100;
       document.getElementById("scroll-fill").style.width = scrolled + "%";
   });

